INSERT INTO document_chunk (
    document_id, chunk_index, content, token_count, embedding_json, embedding_model, embedding_dim
) VALUES (
    #{documentId}, #{chunkIndex}, #{content}, #{tokenCount}, #{embeddingJson}, #{embeddingModel}, #{embeddingDim}
)

mapper.select:
SELECT FROM document_chunk c INNER JOIN kb_document d ON d.id = c.document_id WHERE c.id IN
#{id}
AND d.deleted_at IS NULL AND d.process_status = 'READY'

SELECT , MATCH(c.content) AGAINST (#{query}) AS fulltext_score FROM document_chunk c INNER JOIN kb_document d ON d.id = c.document_id WHERE d.knowledge_base_id = #{knowledgeBaseId} AND d.deleted_at IS NULL AND d.process_status = 'READY' AND c.embedding_json IS NOT NULL
AND c.embedding_model = #{embeddingModel}
AND MATCH(c.content) AGAINST (#{query}) ORDER BY fulltext_score DESC LIMIT #{limit}
